with flattened_attrs as (select id, effective_from, currency, tier_limits, tier_prices, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers) select id, effective_from, entry_price, row_number() over (partition by currency order by effective_from, id) as row_seq, lead(entry_price, 1) over (partition by currency order by entry_price, id) as next_entry_price, first_value(entry_price) ignore nulls over (order by effective_from, id rows between unbounded preceding and current row) as first_known_entry_price from flattened_attrs where effective_from <= '2024-04-29'
